import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.BqNd1sPY.js";const p=JSON.parse('{"title":"D16：准备和检查数据","description":"","frontmatter":{},"headers":[],"relativePath":"02-第3周实战/D16-准备和检查数据.md","filePath":"02-第3周实战/D16-准备和检查数据.md"}'),r={name:"02-第3周实战/D16-准备和检查数据.md"};function l(d,a,c,n,s,_){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="d16-准备和检查数据" tabindex="-1">D16：准备和检查数据 <a class="header-anchor" href="#d16-准备和检查数据" aria-label="Permalink to &quot;D16：准备和检查数据&quot;">​</a></h1><h2 id="认识演示数据" tabindex="-1">认识演示数据 <a class="header-anchor" href="#认识演示数据" aria-label="Permalink to &quot;认识演示数据&quot;">​</a></h2><p><code>data/sample.txt</code> 是为本课程原创的短篇中文演示语料。它规模小、风格单一，适合快速验证管线和观察记忆，不足以训练通用模型。</p><p>打开数据并记录：</p><ul><li>字符数量与不同字符数量。</li><li>训练/验证切分比例。</li><li>最长和最短段落。</li><li>是否有乱码、重复或意外个人信息。</li><li>许可：本仓库课程演示使用。</li></ul><p>代码按文本顺序切前 90% 为训练、后 10% 为验证。这能让演示稳定，但真实项目应根据文档、来源和时间设计切分，并先处理近重复泄漏。</p><h2 id="替换数据的规则" tabindex="-1">替换数据的规则 <a class="header-anchor" href="#替换数据的规则" aria-label="Permalink to &quot;替换数据的规则&quot;">​</a></h2><p>可以把有权使用的 UTF-8 纯文本放入 <code>data/</code>，复制配置并修改 <code>data_path</code>。不要覆盖样例配置。真实语料至少应比 <code>block_size + 1</code> 长很多，且<a href="/LLMTrain/05-速查表/术语速查#term-validation-set" class="wiki-term" data-wiki-title="validation set" data-wiki-summary="不参与梯度更新、用于选择配置和观察泛化表现的数据。" data-wiki-misconception="反复针对验证集调参不会产生信息泄漏。">验证集</a>也必须超过这个长度。</p><h2 id="今日产物-数据卡" tabindex="-1">今日产物：数据卡 <a class="header-anchor" href="#今日产物-数据卡" aria-label="Permalink to &quot;今日产物：数据卡&quot;">​</a></h2><p>复制 <a href="./数据卡模板">数据卡模板</a>，填写来源、许可、处理、切分、限制和不应用途。</p>',10)])])}const m=e(r,[["render",l]]);export{p as __pageData,m as default};
